using System.Collections.Generic;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurifyWithBadEffectAction", menuName = "Data/Battle/Battle Actions/Purification Actions/PurifyWithBadEffect Action")]
public class PurifyWithBadEffectAction : BattleAction
{
	[Header("Purify With Bad Effect Action")]
	[SerializeField]
	private BattleAction purifyAction;

	[SerializeField]
	private OmenLogic targetToApplyDebuffLogic;

	[SerializeField]
	private DefaultEffectAction defaultEffectAction;

	[SerializeField]
	[ShowIf("isAmountPurify")]
	private int effectAmount;

	[SerializeField]
	private bool isAmountPurify;

	[SerializeField]
	[HideIf("isAmountPurify")]
	private int purifyAmount;

	public BattleAction PurifyAction => purifyAction;

	public DefaultEffectAction DefaultEffectAction => defaultEffectAction;

	public int EffectAmount => effectAmount;

	public bool IsAmountPurify => isAmountPurify;

	public int PurifyAmount => purifyAmount;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		purifyAction.CastTargetAmount(target, isAmountPurify ? amount : purifyAmount, source);
		SpawnVFXOnPlayerPosition(4f);
		PlaySFX();
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
		{
			targetToApplyDebuffLogic.ActivateOmen(defaultEffectAction, isAmountPurify ? effectAmount : amount, target, source);
		});
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		purifyAction.AreaCastTargetAmount(targets, isAmountPurify ? amount : purifyAmount, source);
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
		{
			targetToApplyDebuffLogic.ActivateOmen(defaultEffectAction, isAmountPurify ? effectAmount : amount, null, source);
		});
	}
}
